(N'WF-SE-ASSET-01-P-SE-01',N'WF-SE-ASSET-01',N'PH-WF-SE-ASSET-01-02',1,N'Package a reusable technical asset',NULL,NULL,N'Using the approved [demo, script, architecture, response or checklist], create a reusable asset package with purpose, prerequisites, steps, editable parameters, validation checks, known limitations, owner and example use.',N'Reusable asset package.',N'SE removes sensitive content, validates technical accuracy and confirms reuse permissions.',NULL,NULL),
(N'WF-SE-ASSET-01-P-SE-02',N'WF-SE-ASSET-01',N'PH-WF-SE-ASSET-01-01',2,N'Create a technical Skill Blueprint',NULL,NULL,N'Create a reusable Skill Blueprint for [SE workflow]. Define trigger, inputs, trusted sources, ordered steps, expected output, rules, exclusions, exception behavior, human review and one representative test case. Do not publish until tested.',N'Skill Blueprint and test case.',N'SE or skill owner tests representative work and validates access, outputs and safeguards.',NULL,NULL),
(N'WF-SE-QA-01-P-SE-01',N'WF-SE-QA-01',N'PH-WF-SE-QA-01-01',1,N'Draft a grounded technical answer',NULL,NULL,N'Answer the selected technical questions using approved and authoritative sources. For each item provide a grounded answer, source citation, confidence, assumptions and SME-needed flag. Preserve the question order and do not hide unsupported areas.',N'Grounded technical answer matrix.',N'SE and relevant SMEs approve technical, security, legal and product claims.',NULL,NULL),
